package app.util.cliInputFields.common;

import java.util.Scanner;

/**
 * Represents an input field in a command-line interface.
 * Subclasses define how the field is displayed and how its input is read.
 * A field can be created using the builder pattern:
 * <a href="https://refactoring.guru/design-patterns/builder">Builder pattern</a>.
 *
 * @param <T> the data type of the input
 * 
 * AI usage: 
 * javadoc partly generated by DeepAi
 */
public abstract class CLIField<T> {
    /** Scanner used to read input from the command line. */
    protected Scanner scanner;

    /** Message displayed when the input is invalid. */
    protected String errorMessage;

    /** Value used when the user does not provide an input. */
    protected T defaultInput;

    /** Text displayed to prompt the user. */
    protected String readText;

    /**
     * Base builder for constructing {@link CLIField} instances.
     *
     * @param <T> the data type of the field's input
     * @param <B> the concrete builder type, which must extend
     *            {@code Builder<T, B>}
     */
    protected abstract static class Builder<T, B extends Builder<T, B>> {
        /** Scanner used by the field being built. */
        public final Scanner scanner;

        /** Error message used by the field being built. */
        public final String errorMessage;

        /** Default input value for the field being built. */
        public T defaultInput;

        /** Whether a default input value has been set. */
        public boolean hasDefault = false;

        /**
         * Creates a builder with the required scanner and error message.
         *
         * @param scanner scanner used to read input
         * @param errorMessage message displayed when input is invalid
         */
        protected Builder(Scanner scanner, String errorMessage) {
            this.scanner = scanner;
            this.errorMessage = errorMessage;
        }

        /**
         * Returns this builder as its concrete builder type.
         *
         * @return this builder
         */
        protected abstract B self();

        /**
         * Sets the default input value for the field.
         *
         * @param value the default input value
         * @return this builder
         */
        public B defaultInput(T value) {
            this.defaultInput = value;
            this.hasDefault = true;
            return self();
        }

        /**
         * Builds the command-line input field.
         *
         * @return the constructed field
         */
        public abstract CLIField<T> build();
    }

    /**
     * Displays this field's prompt or other relevant text.
     */
    protected abstract void print();

    /**
     * Reads and returns input for this field.
     *
     * @return the input value
     */
    protected abstract T getInput();
}